import{I as o,o as r,c as t,b6 as s,J as l,w as u,j as e,a as p}from"./chunks/framework.BUXTSoD9.js";const b=JSON.parse('{"title":"The Mom Test: Como validar necesidades a traves de entrevistas con usuarios","description":"Aprende a evitar retroalimentacion educada, y haz entrevistas centradas en comportamientos reales, hechos concretos y problemas existentes.","frontmatter":{"title":"The Mom Test: Como validar necesidades a traves de entrevistas con usuarios","description":"Aprende a evitar retroalimentacion educada, y haz entrevistas centradas en comportamientos reales, hechos concretos y problemas existentes."},"headers":[],"relativePath":"es-es/stage-1/appendix-mom-test/index.md","filePath":"es-es/stage-1/appendix-mom-test/index.md"}'),d={name:"es-es/stage-1/appendix-mom-test/index.md"},g=Object.assign(d,{setup(c){const n="Aproximadamente <strong>1.5 horas</strong>";return(m,a)=>{const i=o("ChapterIntroduction");return r(),t("div",null,[a[1]||(a[1]=s('<h1 id="the-mom-test-como-validar-necesidades-a-traves-de-entrevistas-con-usuarios" tabindex="-1">The Mom Test: Como validar necesidades a traves de entrevistas con usuarios <a class="header-anchor" href="#the-mom-test-como-validar-necesidades-a-traves-de-entrevistas-con-usuarios" aria-label="Permalink to “The Mom Test: Como validar necesidades a traves de entrevistas con usuarios”">​</a></h1><p><a id="top-mom"></a></p><h2 id="resumen-del-capitulo" tabindex="-1">Resumen del capitulo <a class="header-anchor" href="#resumen-del-capitulo" aria-label="Permalink to “Resumen del capitulo”">​</a></h2>',3)),l(i,{duration:n,tags:["Entrevistas con usuarios","Validacion de necesidades","Investigacion de usuarios","Investigacion de producto"],coreOutput:"1 conjunto de preguntas de entrevista que obtienen informacion mas real",expectedOutput:"Dejar de tomar la retroalimentacion educada como validacion, y poder juzgar direcciones con comportamientos reales"},{default:u(()=>[...a[0]||(a[0]=[e("p",null,'Muchas personas, la primera vez que hacen investigacion de producto, creen que lo mas importante es "hablar con alguien". Asi que van y preguntan a amigos, colegas e incluso familiares:',-1),e("ul",null,[e("li",null,"Que te parece esta idea?"),e("li",null,"Si existiera un producto asi, lo usarias?"),e("li",null,"Esta funcion suena bastante bien, no?")],-1),e("p",null,"La otra persona suele dar una retroalimentacion muy alentadora:",-1),e("ul",null,[e("li",null,"Esta muy bien"),e("li",null,"Suena util"),e("li",null,"Creo que deberias probarlo")],-1),e("p",null,'El problema es que estas respuestas normalmente no te ayudan a tomar decisiones. Son mas bien cortesia, apoyo, o una reaccion natural para no desanimarte en el momento. Crees haber obtenido "validacion de mercado", pero en realidad solo has recogido un monton de consuelos dificiles de usar para tomar decisiones.',-1),e("p",null,[p("El metodo The Mom Test fue creado precisamente para resolver este problema. Nos recuerda: "),e("strong",null,"no es que los usuarios te esten mintiendo a proposito, sino que tu forma de hacer las preguntas lleva naturalmente a la otra persona hacia respuestas agradables pero inutiles.")],-1)])]),_:1}),a[2]||(a[2]=s(`<div class="info custom-block"><p class="custom-block-title">SOP minimo</p><p><strong>Objetivo</strong>: Despues de leer, sabras mejor como hablar con usuarios sin escuchar solo &quot;suena bien&quot;, sino obtener informacion que realmente te ayude a juzgar la direccion.</p><p><strong>Accion</strong>: Reescribe las 5 preguntas que ibas a hacer, priorizando &quot;cuando fue la ultima vez que paso esto&quot; y &quot;como lo manejaste entonces&quot;.</p><p><strong>Resultado</strong>: Te sera mas facil distinguir que son opiniones y que son verdaderas evidencias para tomar decisiones.</p><p><strong>Enlaces rapidos</strong>: <a href="#mom-what">Que es The Mom Test</a> · <a href="#mom-principles">Tres principios centrales</a> · <a href="#mom-ai">Como te ayuda la IA</a></p></div><h2 id="aprenderas-lo-siguiente" tabindex="-1">Aprenderas lo siguiente <a class="header-anchor" href="#aprenderas-lo-siguiente" aria-label="Permalink to “Aprenderas lo siguiente”">​</a></h2><ol><li>Que problema esta resolviendo exactamente The Mom Test, y por que muchas &quot;investigaciones de usuarios&quot; en realidad no investigan informacion real</li><li>Los principios mas importantes de este metodo: preguntar menos opiniones y mas comportamientos; preguntar menos hipotesis y mas hechos</li><li>Como transformar una pregunta que facilmente genera falsos positivos en una pregunta de entrevista mas valiosa</li><li>Como usar The Mom Test junto con JTBD, validacion de necesidades y evaluacion de MVP</li></ol><p><a id="mom-what"></a></p><h2 id="_1-que-es-exactamente-the-mom-test" tabindex="-1"><a href="#top-mom">1. Que es exactamente The Mom Test</a> <a class="header-anchor" href="#_1-que-es-exactamente-the-mom-test" aria-label="Permalink to “1. Que es exactamente The Mom Test”">​</a></h2><p>The Mom Test proviene del libro homonimo de Rob Fitzpatrick. Su nombre suena como una broma, pero da muy en el clavo:</p><p><strong>Incluso tu madre tendria dificultades para decirte directamente &quot;es una mala idea&quot;.</strong></p><p>La razon no es que no sea honesta, sino:</p><ul><li>No quiere lastimarte</li><li>Te alentara inconscientemente</li><li>Easily seguira tu forma de expresarte al responder</li></ul><p>Y no solo tu madre; amigos, colegas, ex companeros de clase, e incluso muchos desconocidos, al enfrentarse a tu idea de producto, tambien suelen dar &quot;retroalimentacion positiva&quot; similar. Esto no significa que la necesidad sea real, solo significa que formulaste la pregunta de una forma que facilmente obtiene respuestas agradables.</p><p>Por lo tanto, el punto de The Mom Test nunca ha sido &quot;no le preguntes a tu madre&quot;, sino:</p><p><strong>No formules la pregunta de forma que cualquiera te siga la corriente.</strong></p><p>Lo que este metodo realmente quiere ensenarte es como obtener informacion mas cercana a las necesidades reales a traves de la conversacion, en lugar de recoger un monton de comentarios que te hagan sentir bien.</p><h2 id="_2-cual-es-el-problema-central-que-resuelve" tabindex="-1">2. Cual es el problema central que resuelve <a class="header-anchor" href="#_2-cual-es-el-problema-central-que-resuelve" aria-label="Permalink to “2. Cual es el problema central que resuelve”">​</a></h2><p>The Mom Test resuelve principalmente una ilusion cognitiva muy comun:</p><p><strong>Tomar la retroalimentacion positiva por cortesia como una necesidad real.</strong></p><p>Por ejemplo, cuando preguntas:</p><ul><li>Que te parece la idea de esta App?</li><li>Si hiciera una herramienta con IA que te ayude a escribir el curriculum, la usarias?</li><li>Es valiosa esta funcion?</li></ul><p>Estas preguntas tienen en comun:</p><ul><li>Todas preguntan &quot;opiniones&quot;</li><li>Todas tienen cierta insinuacion</li><li>Todas hablan de un futuro que aun no ha ocurrido</li></ul><p>Las respuestas de las personas sobre &quot;opiniones&quot; y &quot;hipotesis futuras&quot; suelen ser inestables. Muchas personas sobreestiman su interes, su capacidad de ejecucion y su disposicion futura a pagar.</p><p>Por eso The Mom Test te recuerda:</p><ul><li>No confies demasiado en las evaluaciones de otros sobre tu idea</li><li>No confies demasiado en las predicciones de otros sobre su comportamiento futuro</li><li>Vuelve siempre a los comportamientos reales que el usuario ya ha tenido</li></ul><p>Porque comparado con &quot;la usarias?&quot;, &quot;como manejaste esto la ultima vez?&quot; suele estar mas cerca de la verdad.</p><p><a id="mom-principles"></a></p><h2 id="_3-los-tres-principios-mas-importantes" tabindex="-1"><a href="#top-mom">3. Los tres principios mas importantes</a> <a class="header-anchor" href="#_3-los-tres-principios-mas-importantes" aria-label="Permalink to “3. Los tres principios mas importantes”">​</a></h2><p>Si solo quieres recordar lo mas importante, empieza con estos tres principios.</p><h3 id="_3-1-habla-menos-de-tu-idea-y-mas-de-las-experiencias-reales-pasadas-del-usuario" tabindex="-1">3.1 Habla menos de tu idea, y mas de las experiencias reales pasadas del usuario <a class="header-anchor" href="#_3-1-habla-menos-de-tu-idea-y-mas-de-las-experiencias-reales-pasadas-del-usuario" aria-label="Permalink to “3.1 Habla menos de tu idea, y mas de las experiencias reales pasadas del usuario”">​</a></h3><p>Muchas entrevistas ineficaces empiezan presentando la propia solucion, hablando de lo emocionado que se esta y del producto que se planea hacer. El problema es que, una vez que hablas demasiado, la otra persona facilmente cambia a un estado de &quot;apoyarte&quot; y &quot;alentarte&quot;.</p><p>En contraste, una mejor forma de hacerlo es centrarse en las experiencias de la otra persona:</p><ul><li>Cuando fue la ultima vez que encontraste este problema?</li><li>Que estabas haciendo en ese momento?</li><li>Como lo resolviste al final?</li><li>Cual fue el paso mas complicado?</li></ul><p>Descubriras que este tipo de preguntas llevan la conversacion de vuelta a la realidad de forma mas natural, en lugar de quedarse en preferencias imaginadas.</p><h3 id="_3-2-pregunta-menos-opiniones-abstractas-y-mas-hechos-concretos" tabindex="-1">3.2 Pregunta menos opiniones abstractas, y mas hechos concretos <a class="header-anchor" href="#_3-2-pregunta-menos-opiniones-abstractas-y-mas-hechos-concretos" aria-label="Permalink to “3.2 Pregunta menos opiniones abstractas, y mas hechos concretos”">​</a></h3><p>&quot;Me parece bien esta funcion&quot;, &quot;suena bien&quot;, &quot;parece util&quot; son expresiones demasiado abstractas para guiar decisiones de producto.</p><p>Informacion mas valiosa suele verse asi:</p><ul><li>La semana pasada pase 2 horas peleando con esto</li><li>Ahora me arreglas con Excel y WeChat</li><li>El mes pasado ya gaste dinero en una herramienta similar</li><li>Lo que mas miedo me da es hacerlo mal, no hacerlo lento</li></ul><p>Esta es la informacion que realmente te ayuda a juzgar la intensidad, frecuencia y posibilidad de pago de un problema.</p><h3 id="_3-3-pregunta-menos-que-solucion-quiere-el-usuario-y-observa-mas-como-resuelve-el-problema-ahora" tabindex="-1">3.3 Pregunta menos que solucion quiere el usuario, y observa mas como resuelve el problema ahora <a class="header-anchor" href="#_3-3-pregunta-menos-que-solucion-quiere-el-usuario-y-observa-mas-como-resuelve-el-problema-ahora" aria-label="Permalink to “3.3 Pregunta menos que solucion quiere el usuario, y observa mas como resuelve el problema ahora”">​</a></h3><p>Los usuarios son muy buenos describiendo sus frustraciones, pero no necesariamente disenando soluciones.</p><p>Si preguntas:</p><ul><li>Te gustaria que una IA te hiciera esto automaticamente?</li><li>Crees que anadir una funcion inteligente seria util?</li></ul><p>Lo que obtienes suele es solo una actitud vaga hacia una solucion, no la necesidad en si.</p><p>Mejores preguntas son:</p><ul><li>Que metodo usas ahora para manejar este problema?</li><li>Por que elegiste esta forma?</li><li>En que falla?</li></ul><p>Entender las soluciones alternativas existentes suele ser mas importante que preguntar directamente &quot;que quieres&quot;.</p><h2 id="_4-por-que-la-gente-siempre-te-da-respuestas-agradables-pero-inutiles" tabindex="-1">4. Por que la gente siempre te da respuestas agradables pero inutiles <a class="header-anchor" href="#_4-por-que-la-gente-siempre-te-da-respuestas-agradables-pero-inutiles" aria-label="Permalink to “4. Por que la gente siempre te da respuestas agradables pero inutiles”">​</a></h2><p>Si puedes entender esto, cometeras menos errores de juicio en las entrevistas.</p><h3 id="_4-1-las-personas-son-inconscientemente-educadas" tabindex="-1">4.1 Las personas son inconscientemente educadas <a class="header-anchor" href="#_4-1-las-personas-son-inconscientemente-educadas" aria-label="Permalink to “4.1 Las personas son inconscientemente educadas”">​</a></h3><p>Especialmente cuando el interlocutor tiene una relacion contigo, le resulta dificil decir directamente:</p><ul><li>Esta direccion no suena muy viable</li><li>No la usaria en absoluto</li><li>Este problema no es tan importante para mi</li></ul><p>Es mas probable que diga &quot;esta muy bien&quot;, &quot;se podria probar cuando haya oportunidad&quot;.</p><h3 id="_4-2-las-personas-sobreestiman-su-yo-futuro" tabindex="-1">4.2 Las personas sobreestiman su yo futuro <a class="header-anchor" href="#_4-2-las-personas-sobreestiman-su-yo-futuro" aria-label="Permalink to “4.2 Las personas sobreestiman su yo futuro”">​</a></h3><p>Mucha gente cree sinceramente que en el futuro:</p><ul><li>Sera mas disciplinada</li><li>Estara mas dispuesta a aprender</li><li>Estara mas dispuesta a pagar</li><li>Estara mas dispuesta a probar herramientas nuevas</li></ul><p>Por eso la frase &quot;si existiera, probablemente la usaria&quot; muchas veces no equivale a que realmente la usara en el futuro.</p><h3 id="_4-3-tu-forma-de-preguntar-ya-esta-guiando-la-respuesta" tabindex="-1">4.3 Tu forma de preguntar ya esta guiando la respuesta <a class="header-anchor" href="#_4-3-tu-forma-de-preguntar-ya-esta-guiando-la-respuesta" aria-label="Permalink to “4.3 Tu forma de preguntar ya esta guiando la respuesta”">​</a></h3><p>Cuando preguntas:</p><ul><li>Te parece buena esta idea?</li><li>Esta funcion te resulta muy util?</li></ul><p>En realidad ya has metido la &quot;respuesta correcta&quot; en la pregunta.</p><p>Es por eso que The Mom Test enfatiza tanto: <strong>no conviertas la entrevista en una busqueda de validacion.</strong></p><h2 id="_5-comparacion-directa-que-preguntas-se-desperdician-facilmente-y-cuales-son-mas-valiosas" tabindex="-1">5. Comparacion directa: que preguntas se desperdician facilmente y cuales son mas valiosas <a class="header-anchor" href="#_5-comparacion-directa-que-preguntas-se-desperdician-facilmente-y-cuales-son-mas-valiosas" aria-label="Permalink to “5. Comparacion directa: que preguntas se desperdician facilmente y cuales son mas valiosas”">​</a></h2><p>Estas comparaciones son utiles para casi todos los principiantes.</p><table tabindex="0"><thead><tr><th>Preguntas que se desperdician facilmente</th><th>Preguntas mas valiosas</th></tr></thead><tbody><tr><td>Que te parece esta idea?</td><td>Cuando fue la ultima vez que encontraste este problema?</td></tr><tr><td>Usarias este producto si existiera?</td><td>Como estas manejando esto ahora?</td></tr><tr><td>Estarias dispuesto a pagar por esta funcion?</td><td>Has gastado dinero en este problema alguna vez? En que?</td></tr><tr><td>Crees que esta funcion es importante?</td><td>Cual es el paso mas molesto, lento o inseguro de este proceso?</td></tr><tr><td>Te gustaria que una IA te hiciera esto automaticamente?</td><td>Por que aun no has encontrado una solucion mas comoda?</td></tr></tbody></table><p>Lo mas importante de esta tabla no son las frases concretas, sino la direccion detras:</p><ul><li>De opiniones hacia hechos</li><li>Del futuro hacia el pasado</li><li>De tu solucion hacia el problema del usuario</li></ul><h2 id="_6-un-ritmo-de-entrevista-que-incluso-un-principiante-puede-usar-inmediatamente" tabindex="-1">6. Un ritmo de entrevista que incluso un principiante puede usar inmediatamente <a class="header-anchor" href="#_6-un-ritmo-de-entrevista-que-incluso-un-principiante-puede-usar-inmediatamente" aria-label="Permalink to “6. Un ritmo de entrevista que incluso un principiante puede usar inmediatamente”">​</a></h2><p>Si quieres ir a hablar con alguien ahora mismo, puedes seguir esta secuencia directamente.</p><h3 id="_6-1-apertura-explica-que-estas-aprendiendo-no-vendiendo" tabindex="-1">6.1 Apertura: explica que estas aprendiendo, no vendiendo <a class="header-anchor" href="#_6-1-apertura-explica-que-estas-aprendiendo-no-vendiendo" aria-label="Permalink to “6.1 Apertura: explica que estas aprendiendo, no vendiendo”">​</a></h3><p>Por ejemplo:</p><blockquote><p>Estoy investigando como la gente maneja este tipo de problemas, quiero entender la situacion real primero, no estoy aqui para vender nada.</p></blockquote><p>Este tipo de expresion ayuda a la otra persona a liberarse de la carga de &quot;tener que darte retroalimentacion positiva&quot;.</p><h3 id="_6-2-empieza-preguntando-por-la-ultima-experiencia-real" tabindex="-1">6.2 Empieza preguntando por la ultima experiencia real <a class="header-anchor" href="#_6-2-empieza-preguntando-por-la-ultima-experiencia-real" aria-label="Permalink to “6.2 Empieza preguntando por la ultima experiencia real”">​</a></h3><p>Puedes empezar con este tipo de preguntas:</p><ul><li>Cuando fue la ultima vez que encontraste este problema?</li><li>Que paso en ese momento?</li><li>Cual fue tu primera reaccion, como lo manejaste?</li></ul><p>Una vez que la conversacion entra en eventos concretos, la calidad de la informacion suele mejorar notablemente.</p><h3 id="_6-3-profundiza-preguntando-sobre-comportamientos-costos-y-soluciones-alternativas" tabindex="-1">6.3 Profundiza preguntando sobre comportamientos, costos y soluciones alternativas <a class="header-anchor" href="#_6-3-profundiza-preguntando-sobre-comportamientos-costos-y-soluciones-alternativas" aria-label="Permalink to “6.3 Profundiza preguntando sobre comportamientos, costos y soluciones alternativas”">​</a></h3><p>Sigue preguntando:</p><ul><li>Que metodo usas ahora para resolverlo?</li><li>Cual es la parte mas incomoda de este metodo?</li><li>Cuanto tiempo, dinero o esfuerzo has invertido en esto?</li><li>Has probado otros metodos? Por que no los seguiste usando?</li></ul><h3 id="_6-4-finalmente-juzga-la-intensidad-del-dolor-y-la-prioridad" tabindex="-1">6.4 Finalmente juzga la intensidad del dolor y la prioridad <a class="header-anchor" href="#_6-4-finalmente-juzga-la-intensidad-del-dolor-y-la-prioridad" aria-label="Permalink to “6.4 Finalmente juzga la intensidad del dolor y la prioridad”">​</a></h3><p>No necesitas preguntar directamente &quot;te duele?&quot;, puedes juzgarlo por los detalles:</p><ul><li>Lo encuentra frecuentemente?</li><li>Ya esta intentando compensar activamente?</li><li>Ya esta dispuesto a invertir costos en esto?</li><li>Cuando habla de esto, muestra emocion evidente?</li></ul><p>Todo esto es mas util que una simple pregunta &quot;es este tu punto de dolor?&quot;.</p><h2 id="_7-un-ejemplo-mas-completo" tabindex="-1">7. Un ejemplo mas completo <a class="header-anchor" href="#_7-un-ejemplo-mas-completo" aria-label="Permalink to “7. Un ejemplo mas completo”">​</a></h2><p>Supongamos que quieres hacer un producto de &quot;IA que ayuda a universitarios a mejorar su curriculum&quot;.</p><h3 id="forma-incorrecta-de-preguntar" tabindex="-1">Forma incorrecta de preguntar <a class="header-anchor" href="#forma-incorrecta-de-preguntar" aria-label="Permalink to “Forma incorrecta de preguntar”">​</a></h3><p>Vas y le preguntas a un companero:</p><blockquote><p>Quiero hacer una herramienta de optimizacion de curriculum con IA, que te parece?<br> Si pudiera modificar automaticamente el curriculum segun el puesto, la usarias?</p></blockquote><p>En este caso, la otra persona probablemente dira:</p><ul><li>Suena bien</li><li>Creo que seria util</li><li>Si es gratis, la probara</li></ul><p>Estas respuestas casi no te ayudan a juzgar si la necesidad es realmente fuerte.</p><h3 id="forma-mejor-de-preguntar" tabindex="-1">Forma mejor de preguntar <a class="header-anchor" href="#forma-mejor-de-preguntar" aria-label="Permalink to “Forma mejor de preguntar”">​</a></h3><p>Podrias cambiar a:</p><blockquote><p>Cuando fue la ultima vez que modificaste tu curriculum?<br> Por que tuviste que modificarlo?<br> Como lo hiciste?<br> Cual fue el paso mas bloqueante?<br> Has pedido a alguien que te lo revise?<br> Has gastado dinero o mucho tiempo alguna vez en el tema del curriculum?</p></blockquote><p>A traves de estas preguntas, la informacion que puedes obtener seria:</p><ul><li>Mucha gente no es que no sepa escribir, sino que no sabe como adaptarlo a diferentes puestos</li><li>Lo mas doloroso no es el formato, sino &quot;no saber que experiencias vale la pena incluir&quot;</li><li>Procrastinan, no por vagos, sino porque cada vez que modifican el curriculum es muy agotador</li><li>Ya estan usando consejos de companeros de cursos superiores, sitios de plantillas, herramientas de IA y revision de amigos para arreglarselas</li></ul><p>En este punto, estas mucho mas cerca del problema real.</p><h2 id="_8-como-usar-the-mom-test-junto-con-jtbd" tabindex="-1">8. Como usar The Mom Test junto con JTBD <a class="header-anchor" href="#_8-como-usar-the-mom-test-junto-con-jtbd" aria-label="Permalink to “8. Como usar The Mom Test junto con JTBD”">​</a></h2><p>Si JTBD te ayuda a ver &quot;que progreso quiere lograr el usuario&quot;, entonces The Mom Test te ensena mas bien:</p><p><strong>Como confirmar a traves de entrevistas si este job realmente existe.</strong></p><p>Puedes perfectamente conectar ambos:</p><ol><li>Primero usa JTBD para hipotetizar un job</li><li>Luego usa el estilo de The Mom Test para preguntar a los usuarios sobre su ultima experiencia real</li><li>Mira si este job es realmente frecuente, real y digno de priorizar</li></ol><p>Por ejemplo, tu hipotesis JTBD es:</p><blockquote><p>Cuando me preparo para enviar candidaturas de practicas, quiero adaptar rapidamente mi curriculum viejo a una version ajustada al puesto, para completar el envio lo antes posible.</p></blockquote><p>Entonces puedes usar preguntas estilo The Mom Test para verificar:</p><ul><li>Cuando fue la ultima vez que enviaste una candidatura?</li><li>Como modificaste tu curriculum en ese momento?</li><li>Que seccion fue la mas dificil de escribir?</li><li>Despues de modificarlo, como juzgabas si era lo suficientemente bueno?</li></ul><p>Asi, los metodos se conectan:</p><ul><li>JTBD te ayuda a definir la hipotesis de necesidad</li><li>The Mom Test te ayuda a verificar la hipotesis a traves de entrevistas</li></ul><h2 id="_9-los-errores-mas-comunes-de-los-principiantes-al-hacer-entrevistas-con-usuarios" tabindex="-1">9. Los errores mas comunes de los principiantes al hacer entrevistas con usuarios <a class="header-anchor" href="#_9-los-errores-mas-comunes-de-los-principiantes-al-hacer-entrevistas-con-usuarios" aria-label="Permalink to “9. Los errores mas comunes de los principiantes al hacer entrevistas con usuarios”">​</a></h2><h3 id="_9-1-convertir-la-entrevista-en-una-presentacion-de-producto" tabindex="-1">9.1 Convertir la entrevista en una presentacion de producto <a class="header-anchor" href="#_9-1-convertir-la-entrevista-en-una-presentacion-de-producto" aria-label="Permalink to “9.1 Convertir la entrevista en una presentacion de producto”">​</a></h3><p>Si hablas demasiado de tu propia idea, la otra persona facilmente empezara a apoyarte en lugar de contarte la situacion real.</p><h3 id="_9-2-entrevistar-solo-a-conocidos" tabindex="-1">9.2 Entrevistar solo a conocidos <a class="header-anchor" href="#_9-2-entrevistar-solo-a-conocidos" aria-label="Permalink to “9.2 Entrevistar solo a conocidos”">​</a></h3><p>Los conocidos pueden ser entrevistados, pero es mas probable que te alienten. Necesitas al menos mezclar con personas mas cercanas a los usuarios reales, en lugar de buscar solo a quienes te apoyan.</p><h3 id="_9-3-persiguir-preguntas-sobre-funciones-demasiado-pronto" tabindex="-1">9.3 Persiguir preguntas sobre funciones demasiado pronto <a class="header-anchor" href="#_9-3-persiguir-preguntas-sobre-funciones-demasiado-pronto" aria-label="Permalink to “9.3 Persiguir preguntas sobre funciones demasiado pronto”">​</a></h3><p>Si aun no has aclarado el problema y empiezas a preguntar sobre botones, interfaces y detalles de funciones, probablemente estas entrando en la solucion demasiado pronto.</p><h3 id="_9-4-tomar-un-la-usaria-como-resultado-de-validacion" tabindex="-1">9.4 Tomar un &quot;la usaria&quot; como resultado de validacion <a class="header-anchor" href="#_9-4-tomar-un-la-usaria-como-resultado-de-validacion" aria-label="Permalink to “9.4 Tomar un &quot;la usaria&quot; como resultado de validacion”">​</a></h3><p>Las entrevistas pueden ayudarte a juzgar la direccion como maximo, no equivalen a una validacion completada. La verdadera validacion, al final, depende de si el usuario esta dispuesto a asumir costos reales, como tiempo, costos de cambio, comportamiento de prueba o incluso pago.</p><h3 id="_9-5-no-organizar-despues-de-la-entrevista" tabindex="-1">9.5 No organizar despues de la entrevista <a class="header-anchor" href="#_9-5-no-organizar-despues-de-la-entrevista" aria-label="Permalink to “9.5 No organizar despues de la entrevista”">​</a></h3><p>Si dejas la informacion ahi, rapidamente se convertira en impresiones vagas. Es mejor organizar lo antes posible:</p><ul><li>Problemas que aparecen con alta frecuencia</li><li>Palabras emocionales en las citas textuales del usuario</li><li>Soluciones alternativas actuales</li><li>Costos ya incurridos</li><li>Tus propios nuevos juicios</li></ul><h2 id="_10-lista-de-preguntas-que-puedes-copiar-y-usar-directamente" tabindex="-1">10. Lista de preguntas que puedes copiar y usar directamente <a class="header-anchor" href="#_10-lista-de-preguntas-que-puedes-copiar-y-usar-directamente" aria-label="Permalink to “10. Lista de preguntas que puedes copiar y usar directamente”">​</a></h2><p>Si quieres empezar rapidamente, aqui tienes un conjunto de preguntas suficientemente generales.</p><h3 id="preguntas-de-apertura" tabindex="-1">Preguntas de apertura <a class="header-anchor" href="#preguntas-de-apertura" aria-label="Permalink to “Preguntas de apertura”">​</a></h3><ul><li>Cuando fue la ultima vez que encontraste este problema?</li><li>Que paso exactamente en ese momento?</li></ul><h3 id="preguntas-sobre-comportamiento" tabindex="-1">Preguntas sobre comportamiento <a class="header-anchor" href="#preguntas-sobre-comportamiento" aria-label="Permalink to “Preguntas sobre comportamiento”">​</a></h3><ul><li>Como lo manejaste en ese momento?</li><li>Por que elegiste esa forma?</li></ul><h3 id="preguntas-sobre-costos" tabindex="-1">Preguntas sobre costos <a class="header-anchor" href="#preguntas-sobre-costos" aria-label="Permalink to “Preguntas sobre costos”">​</a></h3><ul><li>Cuanto tiempo o esfuerzo te suele llevar esto?</li><li>Has gastado dinero alguna vez para resolverlo?</li></ul><h3 id="preguntas-sobre-soluciones-alternativas" tabindex="-1">Preguntas sobre soluciones alternativas <a class="header-anchor" href="#preguntas-sobre-soluciones-alternativas" aria-label="Permalink to “Preguntas sobre soluciones alternativas”">​</a></h3><ul><li>Has probado otras herramientas o metodos?</li><li>Por que no los seguiste usando?</li></ul><h3 id="preguntas-de-cierre" tabindex="-1">Preguntas de cierre <a class="header-anchor" href="#preguntas-de-cierre" aria-label="Permalink to “Preguntas de cierre”">​</a></h3><ul><li>Si volvieras a encontrar el mismo problema en el futuro, como deberia ser la solucion ideal?</li></ul><p>Nota: esta pregunta de cierre puede hacerse, pero es mejor dejarla para el final. Porque primero necesitas obtener hechos, no deseos.</p><h2 id="_11-resumen" tabindex="-1">11. Resumen <a class="header-anchor" href="#_11-resumen" aria-label="Permalink to “11. Resumen”">​</a></h2><p>La contribucion mas importante de The Mom Test no es darte un conjunto de tecnicas para &quot;saber hablar mejor&quot;, sino ayudarte a establecer una forma mas lucida de juzgar:</p><ul><li>No confies demasiado rapido en los elogios de otros sobre tu idea</li><li>No tomes &quot;si existiera, la usaria&quot; como una necesidad real</li><li>No dejes que la entrevista se convierta en una busqueda de validacion</li></ul><p>Las entrevistas verdaderamente valiosas deben volver siempre a estas cosas:</p><ul><li>La ultima experiencia real del usuario</li><li>Como lo maneja ahora</li><li>Que costos ya ha incurrido</li><li>En que areas se siente claramente incomodo</li></ul><p>Cuando empieces a preguntar de esta manera, la informacion que obtengas a veces no sonara tan agradable, pero sera mas util.<br> Y al hacer productos, <strong>la verdad util siempre es mas importante que el elogio agradable.</strong></p><p><a id="mom-ai"></a></p><h2 id="_12-como-usar-la-ia-para-ayudarte-con-las-entrevistas-de-usuarios" tabindex="-1"><a href="#top-mom">12. Como usar la IA para ayudarte con las entrevistas de usuarios</a> <a class="header-anchor" href="#_12-como-usar-la-ia-para-ayudarte-con-las-entrevistas-de-usuarios" aria-label="Permalink to “12. Como usar la IA para ayudarte con las entrevistas de usuarios”">​</a></h2><p>The Mom Test es esencialmente un metodo de &quot;hablar con personas reales&quot;, por lo que la IA no puede sustituir las entrevistas reales. Pero la IA es muy adecuada para asistirte antes, durante y despues de las entrevistas, especialmente para reducir la barrera de entrada de los principiantes.</p><h3 id="_12-1-dejar-que-la-ia-reescriba-las-preguntas-que-se-desperdician-facilmente" tabindex="-1">12.1 Dejar que la IA reescriba las preguntas &quot;que se desperdician facilmente&quot; <a class="header-anchor" href="#_12-1-dejar-que-la-ia-reescriba-las-preguntas-que-se-desperdician-facilmente" aria-label="Permalink to “12.1 Dejar que la IA reescriba las preguntas &quot;que se desperdician facilmente&quot;”">​</a></h3><p>Muchas personas saben que no deberian preguntar &quot;que te parece esta idea?&quot;, pero al abrir la boca vuelven a este tipo de frases. Puedes pasar primero a la IA las preguntas que has preparado, y pedirle que las reescriba:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Estas son las preguntas que quiero hacer en una entrevista con usuarios:</span></span>
<span class="line"><span>[pega tus preguntas]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Por favor reescribelas usando los principios de The Mom Test:</span></span>
<span class="line"><span>1. Elimina las preguntas de opinion</span></span>
<span class="line"><span>2. Elimina las preguntas que hipotizan sobre el futuro</span></span>
<span class="line"><span>3. Cambialas a preguntas que giren en torno a comportamientos reales pasados, soluciones alternativas existentes y costos ya incurridos</span></span>
<span class="line"><span>4. Finalmente, organizalas en una lista de 8-10 preguntas listas para usar en entrevistas</span></span></code></pre></div><p>Una entrada muy basica tambien funciona:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Quiero preguntar a los usuarios:</span></span>
<span class="line"><span>1. Que te parece si hago una herramienta de IA para modificar curriculums?</span></span>
<span class="line"><span>2. La usarias?</span></span>
<span class="line"><span>3. Estarias dispuesto a pagar?</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Por favor ayudame a reescribirlas de una mejor manera.</span></span></code></pre></div><p>La IA podria dar un resultado util como este:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Preguntas reescritas:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Cuando fue la ultima vez que modificaste tu curriculum?</span></span>
<span class="line"><span>2. Por que tuviste que modificarlo?</span></span>
<span class="line"><span>3. Como lo hiciste?</span></span>
<span class="line"><span>4. Cual paso te llevo mas tiempo?</span></span>
<span class="line"><span>5. Has pedido a alguien que te lo revise?</span></span>
<span class="line"><span>6. Has gastado dinero o mucho tiempo alguna vez en modificar tu curriculum?</span></span></code></pre></div><p>Este tipo de resultado es muy util porque transforma directamente tus preguntas &quot;de opinion&quot; en preguntas &quot;de comportamiento real&quot;.</p><h3 id="_12-2-dejar-que-la-ia-genere-guiones-de-entrevista-para-diferentes-perfiles" tabindex="-1">12.2 Dejar que la IA genere guiones de entrevista para diferentes perfiles <a class="header-anchor" href="#_12-2-dejar-que-la-ia-genere-guiones-de-entrevista-para-diferentes-perfiles" aria-label="Permalink to “12.2 Dejar que la IA genere guiones de entrevista para diferentes perfiles”">​</a></h3><p>La misma direccion, para diferentes grupos de personas, tiene diferentes focos de entrevista. Por ejemplo, estudiantes, Recursos Humanos y trabajadores freelance tienen preocupaciones completamente diferentes. Puedes pedir a la IA que genere una version del guion para cada tipo de interlocutor:</p><ul><li>Para usuarios principiantes, enfocate en entender la ultima experiencia real</li><li>Para usuarios intensivos, enfocate en entender las soluciones alternativas y la intensidad del dolor</li><li>Para usuarios de pago, enfocate en entender si ya han incurrido costos por esto</li></ul><p>Asi tendras mas ritmo en las conversaciones reales, en lugar de hacer las mismas preguntas a todo el mundo.</p><p>Por ejemplo, puedes ingresar directamente:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Voy a hablar con dos tipos de personas:</span></span>
<span class="line"><span>1. Universitarios buscando su primera practica</span></span>
<span class="line"><span>2. Companeros de cursos superiores que ya han revisado muchos curriculums para otros</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Por favor dame un guion de entrevista para cada grupo, con 6 preguntas cada uno.</span></span></code></pre></div><p>La IA podria responder:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Para universitarios:</span></span>
<span class="line"><span>1. Cuando fue la ultima vez que enviaste una candidatura de practica?</span></span>
<span class="line"><span>2. Cual fue el paso mas bloqueante en ese momento?</span></span>
<span class="line"><span>3. Como sabes si tu curriculum esta listo para enviar?</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Para companeros de cursos superiores:</span></span>
<span class="line"><span>1. Cuando fue la ultima vez que revisaste el curriculum de alguien?</span></span>
<span class="line"><span>2. Que problemas obvios ves con mas frecuencia?</span></span>
<span class="line"><span>3. En que paso se atascan mas facilmente los estudiantes de primeros cursos?</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>Asi, no tienes que inventar preguntas desde cero, y la preparacion de entrevistas sera mucho mas facil.</p><h3 id="_12-3-dejar-que-la-ia-organice-las-notas-de-entrevista" tabindex="-1">12.3 Dejar que la IA organice las notas de entrevista <a class="header-anchor" href="#_12-3-dejar-que-la-ia-organice-las-notas-de-entrevista" aria-label="Permalink to “12.3 Dejar que la IA organice las notas de entrevista”">​</a></h3><p>Despues de las entrevistas, el problema mas comun no es &quot;falta de informacion&quot;, sino &quot;informacion demasiado dispersa&quot;. La IA es muy adecuada para ayudarte a organizar conversaciones fragmentadas en notas estructuradas:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>A continuacion estan las notas de mis entrevistas con 3 usuarios.</span></span>
<span class="line"><span>Por favor organiza siguiendo la perspectiva de The Mom Test:</span></span>
<span class="line"><span>1. Que contenido es hecho y que es solo opinion</span></span>
<span class="line"><span>2. Cual fue el ultimo comportamiento real del usuario</span></span>
<span class="line"><span>3. Cual es la solucion alternativa actual</span></span>
<span class="line"><span>4. Cuales son los costos de tiempo, dinero o esfuerzo que el usuario ya ha incurrido</span></span>
<span class="line"><span>5. Que problemas se mencionan repetidamente</span></span>
<span class="line"><span>6. Que afirmaciones suenan positivas pero carecen de evidencia</span></span></code></pre></div><p>Este paso es especialmente valioso porque te ayuda a separar lo que &quot;suena bien&quot; de lo que &quot;realmente puede sustentar una decision&quot;.</p><p>Una entrada simple podria ser:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Estas son mis notas despues de hablar con un usuario:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- Dijo que si hubiera una herramienta probablemente la probara</span></span>
<span class="line"><span>- La semana pasada paso una noche entera modificando su curriculum</span></span>
<span class="line"><span>- Ahora depende principalmente de amigos que le revisen</span></span>
<span class="line"><span>- Dijo que lo mas dificil es no saber cuando esta &quot;listo para enviar&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Por favor ayudame a separar que son opiniones y que son hechos.</span></span></code></pre></div><p>La IA podria responder:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Opiniones:</span></span>
<span class="line"><span>- Si hubiera una herramienta probablemente la probara</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Hechos:</span></span>
<span class="line"><span>- La semana pasada paso una noche entera modificando su curriculum</span></span>
<span class="line"><span>- La solucion alternativa actual es pedir a amigos que le revisen</span></span>
<span class="line"><span>- El punto mas dificil es no saber cuando se puede considerar &quot;listo para enviar&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Puntos clave para juzgar la necesidad:</span></span>
<span class="line"><span>- Este problema acaba de ocurrir recientemente</span></span>
<span class="line"><span>- El usuario ya ha invertido un costo de tiempo significativo</span></span>
<span class="line"><span>- La solucion actual depende de otros, es inestable</span></span></code></pre></div><p>Este resultado puede mostrar muy intuitivamente a los principiantes: que frases se pueden usar para tomar decisiones y cuales solo se pueden escuchar.</p><h3 id="_12-4-dejar-que-la-ia-haga-una-ronda-ligera-de-busqueda-en-la-web" tabindex="-1">12.4 Dejar que la IA haga una ronda ligera de busqueda en la web <a class="header-anchor" href="#_12-4-dejar-que-la-ia-haga-una-ronda-ligera-de-busqueda-en-la-web" aria-label="Permalink to “12.4 Dejar que la IA haga una ronda ligera de busqueda en la web”">​</a></h3><p>Si aun no has empezado las entrevistas, primero puedes pedir a la IA que haga una investigacion externa muy ligera, como:</p><ul><li>En comunidades publicas, como se queja la gente recientemente de este problema</li><li>De que se quejan mas los usuarios de las herramientas existentes</li><li>Si los usuarios ya han gastado dinero en problemas similares</li><li>Que soluciones alternativas ya existen en el mercado</li></ul><p>Este tipo de informacion no puede sustituir las entrevistas reales, pero te ayuda a entrar en contexto mas rapidamente, sabiendo por donde empezar a preguntar.</p><p>Por ejemplo, una entrada simple podria ser:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Por favor ayudame a buscar:</span></span>
<span class="line"><span>&quot;De que se quejan mas los universitarios al modificar su curriculum&quot;</span></span>
<span class="line"><span>Organizalo en 5 quejas mas comunes, escritas en lenguaje coloquial.</span></span></code></pre></div><p>La IA podria responder:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Quejas comunes:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. No saber que poner exactamente en el curriculum</span></span>
<span class="line"><span>2. Tener que modificarlo para cada puesto, es muy cansado</span></span>
<span class="line"><span>3. Modificar muchas versiones y seguir sin seguridad de si esta bien</span></span>
<span class="line"><span>4. Nadie puede darme retroalimentacion fiable</span></span>
<span class="line"><span>5. Sentir siempre que no esta listo, por lo que sigo posponiendo</span></span></code></pre></div><p>El valor de este tipo de resultado es que te facilita encontrar un punto de entrada para las entrevistas.</p><h3 id="_12-5-dejar-que-la-ia-actue-como-coach-de-revision-de-entrevistas" tabindex="-1">12.5 Dejar que la IA actue como &quot;coach de revision de entrevistas&quot; <a class="header-anchor" href="#_12-5-dejar-que-la-ia-actue-como-coach-de-revision-de-entrevistas" aria-label="Permalink to “12.5 Dejar que la IA actue como &quot;coach de revision de entrevistas&quot;”">​</a></h3><p>Tambien puedes pasar las notas de una entrevista recien terminada a la IA y pedirle que te haga criticas:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>A continuacion estan las notas de una entrevista con un usuario.</span></span>
<span class="line"><span>Por favor ayudame a revisar desde la perspectiva de The Mom Test:</span></span>
<span class="line"><span>1. Que preguntas son demasiado parecidas a buscar validacion</span></span>
<span class="line"><span>2. Que preguntas tienen una guia obvia</span></span>
<span class="line"><span>3. Donde podria haber profundizado mas en los hechos</span></span>
<span class="line"><span>4. Si pudieras repetirlo, como se podria preguntar mejor en esta conversacion</span></span></code></pre></div><p>Esto es especialmente util para principiantes, porque desarrollaras mas rapidamente una sensibilidad sobre &quot;si realmente estoy recogiendo evidencia o solo recogiendo animos&quot;.</p><h2 id="📚-tareas" tabindex="-1">📚 Tareas <a class="header-anchor" href="#📚-tareas" aria-label="Permalink to “📚 Tareas”">​</a></h2><p>Por favor completa las siguientes tareas basandote en el contenido anterior:</p><ol><li>Elige una direccion de producto que quieras hacer recientemente, y primero escribe 5 preguntas &quot;que se desperdician facilmente&quot; que hubieras hecho originalmente</li><li>Reescribe estas 5 preguntas en un estilo mas acorde con The Mom Test</li><li>Encuentra 3 usuarios potenciales, y al menos una vez logra preguntar &quot;cuando fue la ultima vez que encontraste este problema&quot;</li><li>Despues de la entrevista, organiza 4 tipos de informacion: comportamientos reales, soluciones alternativas, costos incurridos, dificultades que se repiten</li></ol><h2 id="lectura-adicional" tabindex="-1">Lectura adicional <a class="header-anchor" href="#lectura-adicional" aria-label="Permalink to “Lectura adicional”">​</a></h2><ul><li><a href="https://momtestbook.com/" target="_blank" rel="noreferrer">The Mom Test sitio web oficial</a></li><li><a href="https://www.robfitz.com/the-mom-test/" target="_blank" rel="noreferrer">Rob Fitzpatrick: The Mom Test</a></li></ul>`,185))])}}});export{b as __pageData,g as default};
